#include <ansi.h>

inherit EQUIP;

void create() {
    set_name(HIY "软金束带" NOR, ({ "ruanjin sudai", "sudai", "ruanjin" }));
    set_weight(1000);
    if (clonep())
        set_default_object(__FILE__);
    else {
        set("unit", "条");
        set("value", 2000);
        set("material", "cloth");
        set("armor_type", "waist");
        set("armor_prop/armor", 4);
        set("armor_prop/dodge", -1);
        set("wear_msg", "$N围上一条$n。\n");
        set("remove_msg", "$N将$n解了下来。\n");
    }

    setup();
}

