    ob->delete("can_finish");
    ob->delete("shop_list");
    ob->delete("begin_shop");
    ob->delete("auction_start");
    ob->set("auction_end", 1);
    ob->delete("wait_jupai");
    ob->delete("on_jupai");
    ob->delete("now_shop");
    ob->delete("now_price");
    ob->delete("temp_owner");
