    pot = 150 + random(200);
    sc = 15 + random(20);

    if (me->query_temp("marks/李3")) {
        command("hmm " + me->query("id"));
        command("say 我不是已经把地图给过你了吗？");
        return 1;
    } else if (me->query_temp("marks/李2") && me->query("combat_exp") < 10000) {
        command("shake " + me->query("id"));
        command("say 你的江湖经验太浅，何必去惹事上身？");
        return 1;
    } else if (me->query_temp("marks/李2")) {
        say(CYN "李文秀叹道：高昌迷宫里其实什么都没有，这地图你要就拿去好了。\n" NOR);
