int accept_object(object me, object ob) {
    int r;
    if (r = ::accept_object(me, ob))
        return r;

    if (base_name(ob) != JINWUGOU
        && base_name(ob) != ZHUSUO) {
        command("say 你给我这种东西干什么？");
        return 0;
    }

    if (me->query("family/master_id") != query("id"))
        command("say 多谢这位" + RANK_D->query_respect(me) + "将本门宝物交回。");
    else
        command("say 很好，很好！");
    destruct(ob);
    return 1;
